mean3() {
    awk -F'\t' '
        # Skip the header line (first line of the input)
        NR == 1 { next }

        # For each remaining line, check if the third field is numeric
        {
            if ($3 !~ /^[0-9]+\.?[0-9]*$/ && $3 !~ /^[0-9]*\.[0-9]+$/) {
                print "Refusing row " NR ": third field is not numeric"
                next
            }
        }

        # Accumulate the sum and count of valid third-field values
        { sum += $3; count++ }

        # After processing all lines, print the mean if at least one value was read
        END {
            if (count > 0) {
                printf "%.2f\n", sum / count
            } else {
                print "No numeric values found in the third column."
            }
        }
    '
}
